 function draw(){raf=0;if(disposed||!enabled||!visible||document.hidden)return;current+=(target-current)*.14;if(Math.abs(current-target)<.00015)current=target;const pose=artworkPose(current);frame.rotation.set(.04,pose.rotation,-.025+current*.05);frame.position.y=pose.y;camera.position.set(.2*Math.sin(current*Math.PI),.1,pose.z);camera.lookAt(0,.05,0);ring.rotation.y=pose.ringRotation;ring.visible=current>.18;ring.children.forEach(plane=>plane.material.opacity=.38*clamp((current-.18)/.25));renderer.render(scene,camera);renderer.domElement.dataset.progress=current.toFixed(3);renderer.domElement.dataset.renderCount=String(Number(renderer.domElement.dataset.renderCount||0)+1);invalid=false;if(current!==target)schedule()}
 function resize(){if(disposed)return;const box=container.getBoundingClientRect();if(!box.width||!box.height)return;renderer.setSize(box.width,box.height,false);camera.aspect=box.width/box.height;camera.updateProjectionMatrix();invalid=true;schedule()}
