  const shape=new THREE.Shape();shape.moveTo(-1.05,-1.275);shape.lineTo(1.05,-1.275);shape.lineTo(1.05,1.275);shape.lineTo(-1.05,1.275);shape.closePath();const hole=new THREE.Path();hole.moveTo(-.977,-1.202);hole.lineTo(-.977,1.202);hole.lineTo(.977,1.202);hole.lineTo(.977,-1.202);hole.closePath();shape.holes.push(hole);
