  const order=[0,5,2,7,1,4,3,6];
  for(let row=0;row<2;row++)for(let i=0;i<7;i++){const angle=i/7*Math.PI*2,tile=order[(i+row*7)%8],texture=surroundAtlas.clone();texture.repeat.set(.25-.002,.5-.002);texture.offset.set((tile%4)/4+.001,Math.floor(tile/4)===0?.501:.001);texture.needsUpdate=true;const plane=new THREE.Mesh(photoGeometry(),new THREE.MeshBasicMaterial({map:texture,transparent:true,opacity:.38,side:THREE.DoubleSide,toneMapped:false}));plane.position.set(Math.sin(angle)*5.5,row?2.25:-2.35,-2.5+Math.cos(angle)*2);plane.rotation.y=angle*.15;ring.add(plane)}
